"""Final current-guide overlay for the verified joint working-model review."""
from pathlib import Path
import pandas as pd,json,hashlib
O=Path('outputs/dataset_inventory_20261101');J=Path('outputs/joint_borrowed_biomass_20261102')
def apply(views):
    if not (J/'report_verified.json').exists() or not (J/'completed.json').exists():return views
    verified=json.loads((J/'report_verified.json').read_text())
    for name,sha in verified['output_hashes'].items():
        assert hashlib.sha256((J/name).read_bytes()).hexdigest()==sha, 'Joint review changed; verify before updating guide: '+name
    additions=[
      ['B44','2026-11-02','Implementation','Fit raw size observations and annual count contributions in one joint working likelihood','Review implemented; not primary','Shared size covariance enters once; retain six histories and same 45 supported years','outputs/joint_borrowed_biomass_20261102/README.md'],
      ['B45','2026-11-02','Assumption','Use first-order arithmetic-biomass aggregation with fixed sampling variances and allometry','Conditional approximation; tested','Check recentering, size pooling, calendar correlation, year/site influence and finite simulation calibration','outputs/joint_borrowed_biomass_20261102/diagnostics_summary.csv'],
      ['B46','2026-11-02','Hold','Do not equate joint working-model implementation with total uncertainty or primary promotion','Open limits retained','KFM originals, full nonlinear calibration, protected transfer, count-size dependence and allometric uncertainty remain','outputs/joint_borrowed_biomass_20261102/README.md']]
    ledgerpath=Path('docs/BIOMASS_ASSUMPTIONS_AND_CHANGES.csv');ledger=pd.read_csv(ledgerpath);ledger=ledger[~ledger.id.isin(['B44','B45','B46'])];ledger=pd.concat([ledger,pd.DataFrame(additions,columns=ledger.columns)],ignore_index=True);assert len(ledger)>=46 and ledger.id.is_unique;ledger.to_csv(ledgerpath,index=False)
    hist=views['Decision history'];hist=hist[~hist.id.isin(['B44','B45','B46'])].copy();extra=pd.DataFrame(additions,columns=ledger.columns);extra['current_interpretation']='Current review implementation or explicit remaining limit; manuscript unchanged';extra['lifecycle']='Retained evidence / scoped decision';hist=pd.concat([hist,extra],ignore_index=True);hist.to_csv(O/'decision_history.csv',index=False);views['Decision history']=hist;views['Biomass assumptions']=ledger
    rules=views['Current rules'].copy();mask=rules.rule_id.eq('R13');rules.loc[mask,'implementation_status']='Joint first-order size/count/process likelihood implemented and checked for six PISCO histories; no primary promotion';rules.loc[mask,'limitation_or_supersedes']='Conditional working model: pooled sampling variance, count covariance, allometry and expansion fixed. Full nonlinear and total uncertainty remain incomplete.';rules.loc[mask,'evidence_path']=str(J/'README.md');rules.to_csv(O/'current_rules.csv',index=False);views['Current rules']=rules
    questions=views['Questions'].copy();questions.loc[questions.issue_id.eq('U08'),'finding']='Joint borrowed-size/process working likelihood now implemented on unchanged support. KFM original-size holds remain; total uncertainty is not complete.';questions.loc[questions.issue_id.eq('U08'),'next_action']='Review working-model sensitivity and linearization diagnostics; obtain KFM originals; evaluate nonlinear calibration and unestimated sources before primary promotion.';questions.to_csv(O/'unresolved_issues.csv',index=False);views['Questions']=questions
    freeze=views['Freeze readiness'].copy();freeze.loc[freeze.item_id.eq('F3'),'latest_status']='Density roster and donor records reconciled; joint working likelihood implemented; KFM original sizes and final policy freeze still pending';freeze.loc[freeze.item_id.eq('F4'),'latest_status']='Joint size/count/process review checked; first-order approximation and fixed sampling/allometric assumptions disclosed; not total uncertainty';freeze.to_csv(O/'freeze_readiness.csv',index=False);views['Freeze readiness']=freeze
    support=views['Measurement support'].copy();ids=set(pd.read_csv(J/'support.csv').series_id);support['joint_uncertainty_status']=support.series_id.map(lambda s:'Joint first-order working likelihood, review only' if s in ids else 'Not included in this six-history review');support.to_csv(O/'measurement_support_current.csv',index=False);views['Measurement support']=support;views['Biomass support']=support
    for label,file in [('Joint recovery comparison','same_year_comparison.csv'),('Joint recovery scenarios','joint_trends.csv'),('Joint model diagnostics','diagnostics_summary.csv'),('Joint sensitivity','sensitivity_comparison.csv'),('Joint model calibration','simulation_summary.csv')]:
        df=pd.read_csv(J/file);df.to_csv(O/('joint_'+file),index=False);views[label]=df
    path=O/'README.md';text=path.read_text().replace('all 43 dated entries','all 46 dated entries');text+='\n## Joint biomass recovery review\n\n[Same-year results, figure and model limits](../joint_borrowed_biomass_20261102/index.html). Measured sizes, shared size effects and recovery through time are now fitted in one working likelihood. Six histories retain their existing support; 45 comparison-years in the seven-day sensitivity, 44 with the strict rule. Slopes remain similar and intervals widen; all six current and joint intervals include zero. This is a first-order conditional model, not total uncertainty or a primary-analysis change. Interval calibration remains provisional; use the linked diagnostic results before interpreting interval coverage. KFM original-size holds remain.\n';path.write_text(text)
    hashes=json.loads((O/'current_decision_inputs.json').read_text());hashes[str(ledgerpath)]=hashlib.sha256(ledgerpath.read_bytes()).hexdigest()
    for name in ['same_year_comparison.csv','joint_trends.csv','diagnostics_summary.csv','support.csv','sensitivity_comparison.csv','simulation_summary.csv','report_verified.json']:
        p=J/name;hashes[str(p)]=hashlib.sha256(p.read_bytes()).hexdigest()
    (O/'current_decision_inputs.json').write_text(json.dumps(hashes,indent=2))
    return views
